// Des: Tests for ru-acct-acts on the sim, Vietnamese and English: logout, devices, settings, storage, help, feedback, password hand-off, edge pages
// Flo: sim page > run each op > read page state; no force, dry, read mode, bad input, halt pages
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const ac = @import("ru-acct-acts.zig"); const rig = @import("te-rigz-main.zig"); const halt = @import("ru-safe-halt.zig"); const T = std.testing;
test "logout needs force, shows the QR page, and the next action asks for login" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, ac.run(&live, .logo, "")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.out.length")); var frc = rg.ses(rig.cfgOf(), .force); const out = try ac.run(&frc, .logo, ""); try T.expect(out.done); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.out.length")); frc.fake_ms += 600000; try T.expectError(error.NeedLogin, frc.pre(.read)); }
test "devices list works in read mode; remote logout needs force and removes only that device" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var rdo = rg.ses(rig.cfgOf(), .read); const lst = try ac.run(&rdo, .devl, ""); try T.expect(std.mem.indexOf(u8, lst.text, "Chrome Windows") != null and std.mem.indexOf(u8, lst.text, "iPhone") != null); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, ac.run(&live, .devo, "iPhone")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 600000; try T.expect((try ac.run(&frc, .devo, "iPhone")).done); try T.expectEqualStrings("iPhone", try rg.js("Z.st.devout[0]")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.devout.length")); const after = try ac.run(&rdo, .devl, ""); try T.expect(std.mem.indexOf(u8, after.text, "iPhone") == null and std.mem.indexOf(u8, after.text, "Chrome Windows") != null); try T.expectError(error.BadJob, ac.run(&frc, .devo, "")); }
test "notification and language settings are set and read back, in both languages" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect((try ac.run(&ses, .setn, "on")).done); try T.expectEqualStrings("on", try rg.js("Z.st.sets.notify")); try T.expect((try ac.run(&ses, .setn, "off")).done); try T.expectEqualStrings("off", try rg.js("Z.st.sets.notify")); try T.expect((try ac.run(&ses, .setl, "en")).done); try T.expectEqualStrings("en", try rg.js("Z.lang")); try T.expect((try ac.run(&ses, .setn, "on")).done); try T.expectEqualStrings("on", try rg.js("Z.st.sets.notify")); try T.expect((try ac.run(&ses, .setl, "vi")).done); try T.expectEqualStrings("vi", try rg.js("Z.lang")); try T.expectError(error.BadJob, ac.run(&ses, .setn, "maybe")); try T.expectError(error.BadJob, ac.run(&ses, .setl, "fr")); try T.expectError(error.BadJob, ac.run(&ses, .setl, "")); }
test "storage and help are read-only: work in read and dry mode, both languages" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var rdo = rg.ses(rig.cfgOf(), .read); const sto = try ac.run(&rdo, .stor, ""); try T.expectEqualStrings("12 MB", sto.text); var dry = rg.ses(rig.cfgOf(), .dry); const hlp = try ac.run(&dry, .help, ""); try T.expectEqualStrings("help.zalo.me", hlp.text); _ = try rg.js("Z.set('lang','en')"); const eng = try ac.run(&rdo, .stor, ""); try T.expectEqualStrings("12 MB", eng.text); try T.expect(ac.isRead(.stor) and ac.isRead(.help) and ac.isRead(.devl) and !ac.isRead(.logo)); }
test "feedback is ask-first, previews in dry mode, refused in read mode, needs text" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, ac.run(&live, .feed, "great app")); var dry = rg.ses(rig.cfgOf(), .dry); try T.expect(!(try ac.run(&dry, .feed, "great app")).done); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.fb.length")); var rdo = rg.ses(rig.cfgOf(), .read); try T.expectError(error.BadUsage, ac.run(&rdo, .feed, "x")); var frc = rg.ses(rig.cfgOf(), .force); try T.expectError(error.BadJob, ac.run(&frc, .feed, "")); try T.expect((try ac.run(&frc, .feed, "great app")).done); try T.expectEqualStrings("great app", try rg.js("Z.st.fb[0]")); }
test "password is a hand-off: za opens the page and stops, never types; dry only previews" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var dry = rg.ses(rig.cfgOf(), .dry); try T.expect(!(try ac.run(&dry, .pwdz, "")).done); try T.expectEqualStrings("", try rg.js("document.getElementById('p_pw').style.display")); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.HandTask, ac.run(&live, .pwdz, "")); try T.expectEqualStrings("block", try rg.js("document.getElementById('p_pw').style.display")); try T.expectEqual(@as(u8, 4), @import("er-erro-type.zig").exitCode(error.HandTask)); }
test "edge pages: rate limit is unsafe, expired session needs login, old browser needs you" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.overlay('rate')"); try T.expectError(error.Halted, ses.pre(.read)); try T.expect(try halt.classOf(&rg.sto, alo) == .unsf); try rg.sto.haltClear(); _ = try rg.js("Z.overlay('expire')"); try T.expectError(error.NeedLogin, ses.pre(.read)); _ = try rg.js("Z.overlay('old')"); try T.expectError(error.Halted, ses.pre(.read)); try T.expect(try halt.classOf(&rg.sto, alo) == .need); try rg.sto.haltClear(); _ = try rg.js("Z.clearOverlay()"); try ses.pre(.read); }
